import { useEffect, useMemo, useState } from 'react';

const Icon = ({ children }) => <span className="material-symbols-rounded">{children}</span>;
const dateInput = value => value ? new Date(value).toISOString().slice(0, 10) : new Date().toISOString().slice(0, 10);
const initials = value => value.split(/\s+/).map(word => word[0]).slice(0, 2).join('').toUpperCase();
const roles = { DIRECTOR: 'Director', SUBDIRECTOR: 'Subdirector', COACH: 'Entrenador', MONITOR: 'Monitor' };

function useLoad(load, deps = []) {
  const [data, setData] = useState(null); const [error, setError] = useState(''); const [loading, setLoading] = useState(true);
  const refresh = async () => { setLoading(true); setError(''); try { setData(await load()); } catch (err) { setError(err.message); } finally { setLoading(false); } };
  useEffect(() => { void refresh(); }, deps);
  return { data, error, loading, refresh };
}
function Modal({ title, close, children }) { return <div className="modal-backdrop" onMouseDown={event => event.target === event.currentTarget && close()}><section className="card modal modal-wide"><div className="modal-head"><h2>{title}</h2><button className="icon-close" onClick={close}><Icon>close</Icon></button></div>{children}</section></div>; }
function Error({ text }) { return <p className="error">{text}</p>; }
function Loading() { return <div className="loading">Cargando…</div>; }
function Button({ children, ...props }) { return <button className="secondary" {...props}>{children}</button>; }
function Field({ label, children }) { return <label className="field"><span className="eyebrow">{label}</span><span className="input-wrap">{children}</span></label>; }

export function TeamWorkspace({ api, director, readOnly = false, notify, teamId, tab, navigate }) {
  const { data: teams, error, refresh } = useLoad(() => api('/teams'));
  const [creating, setCreating] = useState(false); const [categories, setCategories] = useState(false); const [birthdays, setBirthdays] = useState(false);
  if (error) return <Error text={error} />; if (!teams) return <Loading />;
  if (teamId) {
    const team = teams.find(item => item.id === teamId);
    return team ? <TeamDetail api={api} team={team} director={director} readOnly={readOnly} close={() => navigate('/equipos')} notify={notify} changed={refresh} tab={tab} navigate={navigate} /> : <section className="detail-page"><button className="back-link" onClick={() => navigate('/equipos')}><Icon>arrow_back</Icon> Volver a equipos</button><div className="card empty">No encontramos este equipo o ya no tenés acceso.</div></section>;
  }
  return <><header className="page-head"><div><span className="eyebrow">GESTIÓN DEPORTIVA</span><h1>Tus equipos</h1><p className="subtitle">Plantel, agenda, asistencia y planificación deportiva.</p></div><div className="toolbar"><Button onClick={() => setBirthdays(true)}><Icon>cake</Icon> Cumpleaños</Button>{director && <><Button onClick={() => setCategories(true)}><Icon>sell</Icon> Categorías</Button><Button onClick={() => setCreating(true)}><Icon>add</Icon> Crear equipo</Button></>}</div></header><div className="grid">{teams.map(team => <button className="card team-card interactive-card" key={team.id} onClick={() => navigate(`/equipos/${team.id}`)}><div className="team-mark"><Icon>groups</Icon></div><div><strong>{team.name}</strong><p className="muted">{team.category.name} · Nivel {team.category.level?.replace('LEVEL_', '') || '3'}</p></div><footer>{team._count.players} jugadores</footer></button>)}</div>{!teams.length && <div className="card empty">Todavía no hay equipos.</div>}{creating && <TeamEditor api={api} close={() => setCreating(false)} done={() => { setCreating(false); refresh(); notify('Equipo creado'); }} />}{categories && <CategoryManager api={api} close={() => setCategories(false)} />}{birthdays && <Birthdays api={api} close={() => setBirthdays(false)} />}</>;
}

function Birthdays({ api, close }) {
  const { data, error } = useLoad(() => api('/birthdays?days=30'));
  return <Modal title="Próximos cumpleaños" close={close}>{!data ? <Loading /> : <div className="stack"><Error text={error} />{data.length ? data.map(player => { const date = new Date(player.nextBirthday); return <div className="list-row" key={player.id}><span><strong>{player.name}</strong><small>{player.daysUntil === 0 ? `Cumple hoy · ${player.turningAge} años` : `En ${player.daysUntil} días · cumple ${player.turningAge}`}</small></span><strong>{date.toLocaleDateString('es-AR', { day: '2-digit', month: 'short', timeZone: 'UTC' })}</strong></div>; }) : <p className="empty">No hay cumpleaños en los próximos 30 días.</p>}</div>}</Modal>;
}

function TeamEditor({ api, team, close, done }) {
  const { data: categories } = useLoad(() => api('/categories'));
  const [error, setError] = useState('');
  if (!categories) return <Modal title={team ? 'Editar equipo' : 'Crear equipo'} close={close}><Loading /></Modal>;
  return <Modal title={team ? 'Editar equipo' : 'Crear equipo'} close={close}><form className="modal-form" onSubmit={async event => { event.preventDefault(); try { await api(team ? `/teams/${team.id}` : '/teams', { method: team ? 'PATCH' : 'POST', body: JSON.stringify(Object.fromEntries(new FormData(event.currentTarget))) }); done(); } catch (err) { setError(err.message); } }}><Field label="NOMBRE"><input name="name" required defaultValue={team?.name} /></Field><Field label="CATEGORÍA"><select name="categoryId" defaultValue={team?.category.id}>{categories.map(category => <option key={category.id} value={category.id}>{category.name} · Nivel {category.level?.replace('LEVEL_', '') || '3'}</option>)}</select></Field><Error text={error} /><button className="primary">Guardar</button></form></Modal>;
}

function CategoryManager({ api, close }) {
  const { data: categories, error, refresh } = useLoad(() => api('/categories'));
  const [name, setName] = useState(''); const [level, setLevel] = useState('LEVEL_3');
  return <Modal title="Categorías" close={close}>{!categories ? <Loading /> : <div className="stack"><form className="inline-form" onSubmit={async event => { event.preventDefault(); try { await api('/categories', { method: 'POST', body: JSON.stringify({ name, level }) }); setName(''); setLevel('LEVEL_3'); refresh(); } catch {} }}><input value={name} onChange={e => setName(e.target.value)} placeholder="Nueva categoría" required /><select value={level} onChange={event => setLevel(event.target.value)}><option value="LEVEL_1">Nivel 1</option><option value="LEVEL_2">Nivel 2</option><option value="LEVEL_3">Nivel 3</option></select><Button><Icon>add</Icon></Button></form>{error && <Error text={error} />}{categories.map(category => <div className="list-row" key={category.id}><span><strong>{category.name}</strong><small>Nivel {category.level?.replace('LEVEL_', '') || '3'}</small></span><div><select value={category.level || 'LEVEL_3'} onChange={async event => { await api(`/categories/${category.id}`, { method: 'PATCH', body: JSON.stringify({ level: event.target.value }) }); refresh(); }}><option value="LEVEL_1">Nivel 1</option><option value="LEVEL_2">Nivel 2</option><option value="LEVEL_3">Nivel 3</option></select><button className="text-action" onClick={async () => { const name = prompt('Nuevo nombre', category.name); if (name?.trim()) { try { await api(`/categories/${category.id}`, { method:'PATCH', body:JSON.stringify({ name }) }); refresh(); } catch (err) { alert(err.message); } } }}>Renombrar</button><button className="text-action danger" onClick={async () => { if (confirm(`¿Archivar ${category.name}?`)) { try { await api(`/categories/${category.id}`, { method: 'DELETE' }); refresh(); } catch (err) { alert(err.message); } } }}>Archivar</button></div></div>)}</div>}</Modal>;
}

function TeamDetail({ api, team, director, readOnly, close, notify, changed, tab: requestedTab, navigate }) {
  const [editor, setEditor] = useState(false);
  const sections = [
    ['plantel', 'groups', 'Plantel', 'Jugadores e importación CSV'],
    ['agenda', 'calendar_month', 'Agenda', 'Entrenamientos, partidos y actividades'],
    ['planificacion', 'event_note', 'Planificación', 'Objetivos, cargas y ejercicios'],
    ['asistencia', 'fact_check', 'Asistencia', 'Registro de cada jornada'],
    ['estadisticas', 'bar_chart', 'Estadísticas', 'Evolución y detalle por jugador'],
    ['plan', 'target', 'Plan de trabajo', 'Focos semanales, mensuales y de temporada']
  ];
  if (director) sections.push(['staff', 'manage_accounts', 'Personal', 'Entrenadores y monitores asignados']);
  const selected = sections.find(([key]) => key === requestedTab);
  const content = selected && {
    plantel: <Roster api={api} team={team} notify={notify} navigate={navigate} />,
    agenda: <Events api={api} team={team} notify={notify} />,
    planificacion: <TrainingPlans api={api} team={team} notify={notify} />,
    asistencia: <Attendance api={api} team={team} notify={notify} />,
    estadisticas: <Statistics api={api} team={team} />,
    plan: <Plan api={api} team={team} notify={notify} />,
    staff: <TeamStaff api={api} team={team} notify={notify} />
  }[requestedTab];
  if (selected && content) return <TeamFeatureView team={team} section={selected} readOnly={readOnly} back={() => navigate(`/equipos/${team.id}`)}>{content}</TeamFeatureView>;
  return <section className="detail-page"><button className="back-link" onClick={close}><Icon>arrow_back</Icon> Equipos</button><header className="detail-head"><div><span className="eyebrow">EQUIPO</span><h1>{team.name}</h1><p className="subtitle">{team.category.name} · Nivel {team.category.level?.replace('LEVEL_', '') || '3'} · {team._count.players} jugadores</p></div>{director && <div className="toolbar"><Button onClick={() => setEditor(true)}><Icon>edit</Icon> Editar</Button><button className="text-action danger" onClick={async () => { if(confirm(`¿Archivar ${team.name}?`)){ await api(`/teams/${team.id}`,{method:'DELETE'}); changed(); close(); notify('Equipo archivado'); } }}>Archivar</button></div>}</header><div className="feature-grid">{sections.map(([key, icon, label, description]) => <button className="card feature-link" key={key} onClick={() => navigate(`/equipos/${team.id}/${key}`)}><Icon>{icon}</Icon><span><strong>{label}</strong><small>{description}</small></span><Icon>chevron_right</Icon></button>)}</div>{editor && <TeamEditor api={api} team={team} close={() => setEditor(false)} done={() => { setEditor(false); changed(); notify('Equipo actualizado'); }} />}</section>;
}

function TeamFeatureView({ team, section, readOnly, back, children }) {
  const [, icon, title, description] = section;
  return <section className={`detail-page feature-page${readOnly ? ' read-only' : ''}`}><button className="back-link" onClick={back}><Icon>arrow_back</Icon> {team.name}</button><header className="detail-head"><div><span className="eyebrow">{team.name.toUpperCase()}</span><h1><Icon>{icon}</Icon> {title}</h1><p className="subtitle">{description}</p></div></header><div className="card detail-content">{children}</div></section>;
}

function TrainingPlans({ api, team, notify }) { const { data, refresh } = useLoad(() => api(`/teams/${team.id}/training-plans`)); const [editing, setEditing] = useState(null); if (!data) return <Loading />; return <div className="stack"><Button onClick={() => setEditing({})}><Icon>add</Icon> Planificar entrenamiento</Button><p className="notice">Cada planificación se vincula a una actividad existente de la Agenda.</p>{data.length ? data.map(plan => <article className="card training-card" key={plan.id}><div><span className="eyebrow">{new Date(plan.scheduledFor).toLocaleDateString('es-AR')} · {plan.event?.title}</span><strong>{plan.title}</strong><p>{plan.mainObjective}</p><small>Intensidad {plan.intensity}/5 · Carga {plan.cognitiveLoad === 'LOW' ? 'baja' : plan.cognitiveLoad === 'HIGH' ? 'alta' : 'media'}</small></div><div><button className="text-action" onClick={() => setEditing(plan)}>Editar</button><button className="text-action danger" onClick={async()=>{if(confirm('¿Eliminar planificación?')){await api(`/training-plans/${plan.id}`,{method:'DELETE'});refresh();notify('Planificación eliminada');}}}>Eliminar</button></div></article>) : <div className="empty">Todavía no hay entrenamientos planificados. Primero creá una actividad en Agenda.</div>}{editing && <TrainingPlanEditor api={api} team={team} plan={editing.id ? editing : null} close={()=>setEditing(null)} done={()=>{setEditing(null);refresh();notify('Planificación guardada');}} />}</div>; }
function TrainingPlanEditor({ api, team, plan, close, done }) { const { data: events } = useLoad(() => api(`/teams/${team.id}/events`)); const [error,setError]=useState(''); if(!events) return <Modal title="Planificar entrenamiento" close={close}><Loading /></Modal>; return <Modal title={plan?'Editar entrenamiento':'Planificar entrenamiento'} close={close}><form className="modal-form" onSubmit={async event=>{event.preventDefault();const data=Object.fromEntries(new FormData(event.currentTarget));data.intensity=Number(data.intensity);try{await api(plan?`/training-plans/${plan.id}`:`/teams/${team.id}/training-plans`,{method:plan?'PATCH':'POST',body:JSON.stringify(data)});done();}catch(err){setError(err.message)}}}><Field label="ENTRENAMIENTO DE AGENDA"><select name="eventId" required defaultValue={plan?.eventId || ''}><option value="" disabled>Seleccioná un entrenamiento</option>{events.map(item=><option key={item.id} value={item.id}>{new Date(item.startsAt).toLocaleDateString('es-AR')} · {item.title}</option>)}</select></Field>{!events.length && <p className="error">No hay actividades disponibles. Creá el entrenamiento desde Agenda antes de planificarlo.</p>}<Field label="NOMBRE DE LA SESIÓN"><input name="title" required defaultValue={plan?.title} placeholder="Ej. Transición defensiva" /></Field><Field label="OBJETIVO PRINCIPAL"><input name="mainObjective" required defaultValue={plan?.mainObjective} placeholder="Ej. Mejorar balance defensivo" /></Field><label className="field"><span className="eyebrow">OBJETIVOS SECUNDARIOS</span><textarea name="secondaryGoals" defaultValue={plan?.secondaryGoals||''} /></label><Field label="INTENSIDAD FÍSICA (1–5)"><select name="intensity" defaultValue={plan?.intensity||3}>{[1,2,3,4,5].map(n=><option value={n} key={n}>{n} · {['Muy baja','Baja','Media','Alta','Máxima'][n-1]}</option>)}</select></Field><Field label="CARGA COGNITIVA"><select name="cognitiveLoad" defaultValue={plan?.cognitiveLoad||'MEDIUM'}><option value="LOW">Baja</option><option value="MEDIUM">Media</option><option value="HIGH">Alta</option></select></Field><label className="field"><span className="eyebrow">EJERCICIOS Y TIEMPOS</span><textarea name="exercises" defaultValue={plan?.exercises||''} placeholder={'1. Activación — 10 min\n2. Ejercicio principal — 25 min'} /></label><label className="field"><span className="eyebrow">NOTAS</span><textarea name="notes" defaultValue={plan?.notes||''} /></label><Error text={error}/><button className="primary" disabled={!events.length}>Guardar planificación</button></form></Modal>; }

function Roster({ api, team, notify, navigate }) {
  const { data: players, error, refresh } = useLoad(() => api('/players'));
  const [creating, setCreating] = useState(false); const [importing, setImporting] = useState(false);
  if (!players) return <Loading />; const roster = players.filter(player => player.teams.some(item => item.teamId === team.id));
  function exportCsv() { const lines = [['Nombre', 'Nacimiento'], ...roster.map(p => [p.name, p.birthDate])].map(row => row.map(value => `"${String(value).replaceAll('"', '""')}"`).join(',')).join('\r\n'); const url = URL.createObjectURL(new Blob([`\uFEFF${lines}`], { type: 'text/csv' })); const link = document.createElement('a'); link.href = url; link.download = `plantel-${team.name.toLowerCase().replaceAll(' ', '-')}.csv`; link.click(); URL.revokeObjectURL(url); }
  return <div className="stack"><div className="toolbar"><Button onClick={() => setCreating(true)}><Icon>person_add</Icon> Jugador</Button><Button onClick={() => setImporting(true)}><Icon>upload_file</Icon> Importar CSV</Button><Button onClick={exportCsv}><Icon>download</Icon> CSV</Button></div>{error && <Error text={error} />}{roster.map(player => <button className="list-row selectable" key={player.id} onClick={() => navigate(`/jugadores/${player.id}`)}><span className="avatar">{initials(player.name)}</span><span><strong>{player.name}</strong><small>{player.birthDate}</small></span><Icon>chevron_right</Icon></button>)}{!roster.length && <div className="empty">No hay jugadores en este equipo.</div>}{creating && <PlayerEditor api={api} team={team} close={() => setCreating(false)} done={() => { setCreating(false); refresh(); notify('Jugador creado'); }} />}{importing && <ImportPlayers api={api} team={team} close={() => setImporting(false)} done={() => { setImporting(false); refresh(); notify('Importación completada'); }} />}</div>;
}

export function PlayerWorkspace({ api, readOnly = false, notify, playerId, tab, navigate }) {
  const { data: players, error, refresh } = useLoad(() => api('/players'));
  const { data: teams } = useLoad(() => api('/teams'));
  const [query, setQuery] = useState(''); const [teamFilter, setTeamFilter] = useState(''); const [creating, setCreating] = useState(false);
  if (!players || !teams) return <Loading />;
  if (playerId) {
    const player = players.find(item => item.id === playerId);
    return player ? <PlayerDetail api={api} player={player} teams={teams} readOnly={readOnly} close={() => navigate('/jugadores')} refresh={refresh} notify={notify} tab={tab} navigate={navigate} /> : <section className="detail-page"><button className="back-link" onClick={() => navigate('/jugadores')}><Icon>arrow_back</Icon> Volver a jugadores</button><div className="card empty">No encontramos este jugador o ya no tenés acceso.</div></section>;
  }
  const visible = players.filter(player => player.name.toLowerCase().includes(query.toLowerCase()) && (!teamFilter || player.teams.some(item => item.teamId === teamFilter)));
  return <><header className="page-head"><div><span className="eyebrow">PLANTEL</span><h1>Jugadores</h1><p className="subtitle">Directorio, ficha deportiva y seguimientos.</p></div><div className="toolbar"><input className="search" value={query} onChange={event => setQuery(event.target.value)} placeholder="Buscar por nombre" /><select className="secondary" value={teamFilter} onChange={e => setTeamFilter(e.target.value)}><option value="">Todos los equipos</option>{teams.map(t => <option key={t.id} value={t.id}>{t.name}</option>)}</select>{!readOnly && <Button onClick={() => setCreating(true)}><Icon>person_add</Icon> Jugador</Button>}</div></header><Error text={error} /><div className="list">{visible.map(player => <button className="card list-row selectable" key={player.id} onClick={() => navigate(`/jugadores/${player.id}`)}><span className="avatar">{initials(player.name)}</span><span><strong>{player.name}</strong><small>{player.position || 'Sin posición'} · {player.teams.length} equipo(s)</small></span><Icon>chevron_right</Icon></button>)}</div>{!visible.length && <div className="card empty">No hay jugadores que coincidan.</div>}{creating && <PlayerEditor api={api} teams={teams} close={() => setCreating(false)} done={() => { setCreating(false); refresh(); notify('Jugador creado'); }} />}</>;
}

function ImportPlayers({ api, team, close, done }) {
  const [rows, setRows] = useState(''); const [fileName, setFileName] = useState(''); const [error, setError] = useState('');
  const isoDate = value => {
    const clean = value.trim();
    if (/^\d{4}-\d{2}-\d{2}$/.test(clean)) return clean;
    const parts = clean.split('/');
    return parts.length === 3 && parts[0].length === 2 ? `${parts[2]}-${parts[1]}-${parts[0]}` : '';
  };
  const normalizeName = value => value.trim().replace(/\s+/g, ' ').replace(/^([^,]+),\s*(.+)$/, '$2 $1').trim();
  const parse = value => {
    const lines = value.replace(/^\uFEFF/, '').split(/\r?\n/).filter(Boolean);
    if (!lines.length) return [];
    const separator = lines[0].includes(';') ? ';' : ',';
    const cells = line => line.split(separator).map(item => item.trim().replace(/^"|"$/g, ''));
    const header = cells(lines[0]).map(value => value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase());
    const nameIndex = header.findIndex(value => value === 'NOMBRE' || value === 'NOMBRE COMPLETO');
    const birthIndex = header.findIndex(value => value === 'FECHA NACIMIENTO' || value === 'FECHA DE NACIMIENTO' || value === 'NACIMIENTO');
    const typeIndex = header.findIndex(value => value === 'TIPO');
    const statusIndex = header.findIndex(value => value === 'ESTADO LICENCIA' || value === 'ESTADO');
    const removalIndex = header.findIndex(value => value === 'BAJA');
    if (nameIndex >= 0 && birthIndex >= 0) return lines.slice(1).map(cells).filter(row => {
      const type = typeIndex >= 0 ? row[typeIndex]?.toUpperCase() : 'JUGADOR';
      const status = statusIndex >= 0 ? row[statusIndex]?.toUpperCase() : '';
      return type === 'JUGADOR' && status !== 'BAJA' && !(removalIndex >= 0 && row[removalIndex]);
    }).map(row => ({ name: normalizeName(row[nameIndex] || ''), birthDate: isoDate(row[birthIndex] || '') })).filter(player => player.name && /^\d{4}-\d{2}-\d{2}$/.test(player.birthDate));
    return lines.map(cells).filter(row => row.length >= 2).map(([name, birthDate]) => ({ name: normalizeName(name), birthDate: isoDate(birthDate) })).filter(player => player.name && /^\d{4}-\d{2}-\d{2}$/.test(player.birthDate));
  };
  return <Modal title="Importar jugadores" close={close}><form className="modal-form" onSubmit={async event => { event.preventDefault(); const players = parse(rows); if (!players.length) return setError('No encontramos jugadores activos con nombre y fecha de nacimiento válidos.'); try { const result = await api(`/teams/${team.id}/players/import`, { method: 'POST', body: JSON.stringify({ players }) }); alert(`Creados: ${result.created}. Omitidos: ${result.skipped}.`); done(); } catch (err) { setError(err.message); } }}><p className="notice">Compatible con planillas de licencias: importa <strong>JUGADOR</strong> activos y excluye entrenadores, trainers y bajas.</p><label className="file-picker"><Icon>upload_file</Icon><span>{fileName || 'Seleccionar archivo CSV'}</span><input type="file" accept=".csv,text/csv" onChange={async event => { const file = event.target.files?.[0]; if (!file) return; const buffer = await file.arrayBuffer(); let text = new TextDecoder('utf-8').decode(buffer); if (text.includes('�')) text = new TextDecoder('windows-1252').decode(buffer); setFileName(file.name); setRows(text); setError(''); }} /></label><textarea rows="9" value={rows} onChange={e => { setRows(e.target.value); setFileName(''); }} placeholder={'NOMBRE;FECHA NACIMIENTO;TIPO\nAPELLIDO, NOMBRE;20/04/2010;JUGADOR'} /><p className="notice">{rows ? `${parse(rows).length} jugador(es) activo(s) válido(s) detectado(s).` : 'Máximo 300 jugadores por importación.'}</p><Error text={error} /><button className="primary">Importar jugadores</button></form></Modal>;
}

function PlayerEditor({ api, team, teams, player, close, done }) {
  const [error, setError] = useState('');
  const fields = [['Posición', 'position'], ['Club actual', 'currentClub'], ['Altura (cm)', 'heightCm', 'number'], ['Peso (kg)', 'weightKg', 'number'], ['Envergadura (cm)', 'wingspanCm', 'number'], ['Salto vertical (cm)', 'verticalJumpCm', 'number'], ['Tiro exterior (1–10)', 'outsideShooting', 'number'], ['Defensa 1v1 (1–10)', 'defenseOneOnOne', 'number'], ['IQ basket (1–10)', 'basketballIQ', 'number']];
  return <Modal title={player ? 'Editar jugador' : 'Crear jugador'} close={close}><form className="modal-form" onSubmit={async event => { event.preventDefault(); const form = Object.fromEntries(new FormData(event.currentTarget)); for (const key of ['heightCm', 'weightKg', 'wingspanCm', 'verticalJumpCm', 'outsideShooting', 'defenseOneOnOne', 'basketballIQ']) if (form[key] === '') delete form[key]; else form[key] = Number(form[key]); try { if (player) await api(`/players/${player.id}`, { method: 'PATCH', body: JSON.stringify(form) }); else { form.teamIds = teams ? [...event.currentTarget.elements.teamIds.selectedOptions].map(x => x.value) : [team.id]; await api('/players', { method: 'POST', body: JSON.stringify(form) }); } done(); } catch (err) { setError(err.message); } }}><Field label="NOMBRE"><input name="name" defaultValue={player?.name} required /></Field><Field label="NACIMIENTO"><input name="birthDate" type="date" defaultValue={dateInput(player?.birthDate)} required /></Field>{!player && teams && <Field label="EQUIPOS (MÁXIMO 2)"><select name="teamIds" multiple size="3">{teams.map(item => <option value={item.id} key={item.id}>{item.name}</option>)}</select></Field>}{fields.map(([label, key, type]) => <Field key={key} label={label}><input name={key} type={type || 'text'} defaultValue={player?.[key] ?? ''} /></Field>)}<label className="field"><span className="eyebrow">OBSERVACIONES DEPORTIVAS</span><textarea name="scoutingNotes" defaultValue={player?.scoutingNotes ?? ''} /></label><Error text={error} /><button className="primary">Guardar</button></form></Modal>;
}

function PlayerDetail({ api, player, teams, readOnly, close, refresh, notify, tab: requestedTab, navigate }) {
  const [editing, setEditing] = useState(false);
  const sections = [['perfil', 'badge', 'Perfil deportivo', 'Datos físicos y observaciones'], ['seguimiento', 'monitoring', 'Seguimiento', 'Evaluaciones semanales y mensuales'], ['equipos', 'groups', 'Equipos', 'Asignación a equipos']];
  const selected = sections.find(([key]) => key === requestedTab);
  const profile = <PlayerProfile player={player} onArchive={async () => { if (confirm('¿Archivar este jugador?')) { await api(`/players/${player.id}`, { method: 'DELETE' }); refresh(); close(); notify('Jugador archivado'); } }} />;
  const content = selected && { perfil: profile, seguimiento: <ProgressNotes api={api} player={player} notify={notify} />, equipos: <PlayerTeams api={api} player={player} teams={teams} refresh={refresh} notify={notify} /> }[requestedTab];
  if (selected && content) return <PlayerFeatureView player={player} section={selected} readOnly={readOnly} back={() => navigate(`/jugadores/${player.id}`)}>{content}</PlayerFeatureView>;
  return <section className="detail-page"><button className="back-link" onClick={close}><Icon>arrow_back</Icon> Jugadores</button><header className="detail-head"><div><span className="eyebrow">FICHA DEL JUGADOR</span><h1>{player.name}</h1><p className="subtitle">{player.position || 'Sin posición'} · {player.currentClub || 'Sin club'}</p></div>{!readOnly && <Button onClick={() => setEditing(true)}><Icon>edit</Icon> Editar</Button>}</header><div className="feature-grid">{sections.map(([key, icon, title, description]) => <button className="card feature-link" key={key} onClick={() => navigate(`/jugadores/${player.id}/${key}`)}><Icon>{icon}</Icon><span><strong>{title}</strong><small>{description}</small></span><Icon>chevron_right</Icon></button>)}</div>{editing && <PlayerEditor api={api} player={player} close={() => setEditing(false)} done={() => { setEditing(false); refresh(); notify('Jugador actualizado'); }} />}</section>;
}

function PlayerFeatureView({ player, section, readOnly, back, children }) {
  const [, icon, title, description] = section;
  return <section className={`detail-page feature-page${readOnly ? ' read-only' : ''}`}><button className="back-link" onClick={back}><Icon>arrow_back</Icon> {player.name}</button><header className="detail-head"><div><span className="eyebrow">JUGADOR</span><h1><Icon>{icon}</Icon> {title}</h1><p className="subtitle">{description}</p></div></header><div className="card detail-content">{children}</div></section>;
}

function PlayerProfile({ player, onArchive }) {
  const missing = value => value === null || value === undefined || value === '' ? 'Sin registrar' : value;
  const birth = player.birthDate ? new Date(player.birthDate) : null;
  const years = birth ? new Date().getFullYear() - birth.getFullYear() - (new Date() < new Date(new Date().getFullYear(), birth.getMonth(), birth.getDate()) ? 1 : 0) : null;
  const data = [
    ['calendar_month', 'Nacimiento', birth ? `${birth.toLocaleDateString('es-AR')} · ${years} años` : null],
    ['sports_basketball', 'Posición', player.position],
    ['shield', 'Club actual', player.currentClub],
    ['groups', 'Equipos asignados', `${player.teams?.length || 0} de 2`],
    ['straighten', 'Altura', player.heightCm ? `${player.heightCm} cm` : null],
    ['monitor_weight', 'Peso', player.weightKg ? `${player.weightKg} kg` : null],
    ['accessibility_new', 'Envergadura', player.wingspanCm ? `${player.wingspanCm} cm` : null],
    ['vertical_align_top', 'Salto vertical', player.verticalJumpCm ? `${player.verticalJumpCm} cm` : null],
    ['sports_score', 'Tiro exterior', player.outsideShooting ? `${player.outsideShooting}/10` : null],
    ['security', 'Defensa 1v1', player.defenseOneOnOne ? `${player.defenseOneOnOne}/10` : null],
    ['psychology', 'IQ basket', player.basketballIQ ? `${player.basketballIQ}/10` : null]
  ];
  return <div className="stack"><section><span className="eyebrow">INFORMACIÓN DEL JUGADOR</span><div className="player-facts">{data.map(([icon, label, value]) => <div className="player-fact" key={label}><Icon>{icon}</Icon><span><small>{label}</small><strong className={value ? '' : 'is-missing'}>{missing(value)}</strong></span></div>)}</div></section><section className="player-notes"><span className="eyebrow">OBSERVACIONES DEPORTIVAS</span><p>{player.scoutingNotes || 'Sin observaciones deportivas registradas.'}</p></section><button className="text-action danger" onClick={onArchive}>Archivar jugador</button></div>;
}

function PlayerTeams({ api, player, teams, refresh, notify }) { const memberships = new Set(player.teams.map(x => x.teamId)); return <div className="stack">{teams.map(team => <label className="list-row" key={team.id}><span><strong>{team.name}</strong><small>{team.category?.name}</small></span><input type="checkbox" checked={memberships.has(team.id)} onChange={async event => { try { await api(`/teams/${team.id}/players/${player.id}`, { method: event.target.checked ? 'POST' : 'DELETE' }); refresh(); notify('Asignación actualizada'); } catch (err) { alert(err.message); } }} /></label>)}</div>; }

function Events({ api, team, notify }) { const { data, error, refresh } = useLoad(() => api(`/teams/${team.id}/events`)); const [editing, setEditing] = useState(null); const [attendance, setAttendance] = useState(null); if (!data) return <Loading />; return <div className="stack"><Button onClick={() => setEditing({})}><Icon>add</Icon> Actividad</Button><Error text={error} />{data.map(event => <div className="list-row" key={event.id}><span><strong>{event.title}</strong><small>{new Date(event.startsAt).toLocaleString('es-AR')} · {event.attendanceSession ? 'Asistencia completada' : 'Sin asistencia'}</small></span><div>{new Date(event.startsAt) <= new Date() && <button className="text-action" onClick={() => setAttendance(event)}>{event.attendanceSession ? 'Ver asistencia' : 'Tomar asistencia'}</button>}<button className="text-action" onClick={() => setEditing(event)}>Editar</button><button className="text-action danger" onClick={async () => { if (confirm('¿Eliminar actividad?')) { await api(`/events/${event.id}`, { method: 'DELETE' }); refresh(); } }}>Eliminar</button></div></div>)}{editing && <EventEditor api={api} team={team} event={editing.id ? editing : null} close={() => setEditing(null)} done={() => { setEditing(null); refresh(); notify('Agenda actualizada'); }} />}{attendance && <AttendanceEditor api={api} team={team} session={attendance.attendanceSession ? { ...attendance.attendanceSession, eventId: attendance.id } : null} event={attendance} close={() => setAttendance(null)} done={() => { setAttendance(null); refresh(); notify('Asistencia guardada'); }} />}</div>; }
function EventEditor({ api, team, event, close, done }) { const [error, setError] = useState(''); return <Modal title={event ? 'Editar actividad' : 'Nueva actividad'} close={close}><form className="modal-form" onSubmit={async formEvent => { formEvent.preventDefault(); const data = Object.fromEntries(new FormData(formEvent.currentTarget)); data.notes = data.notes || null; data.repeatWeekly = data.repeatWeekly === 'on'; data.repeatWeekdays = data.repeatWeekly ? [new Date(data.startsAt).getDay() || 7] : []; if (!data.repeatUntil) delete data.repeatUntil; try { await api(event ? `/events/${event.id}` : `/teams/${team.id}/events`, { method: event ? 'PATCH' : 'POST', body: JSON.stringify(data) }); done(); } catch (err) { setError(err.message); } }}><Field label="TÍTULO"><input name="title" defaultValue={event?.title} required /></Field><Field label="INICIO"><input name="startsAt" type="datetime-local" defaultValue={event ? new Date(event.startsAt).toISOString().slice(0, 16) : ''} required /></Field><Field label="FINALIZACIÓN"><input name="endsAt" type="datetime-local" defaultValue={event ? new Date(event.endsAt).toISOString().slice(0, 16) : ''} required /></Field><label className="list-row"><span><strong>Repetir semanalmente</strong><small>Creará una actividad por semana hasta la fecha elegida.</small></span><input name="repeatWeekly" type="checkbox" /></label><Field label="REPETIR HASTA"><input name="repeatUntil" type="date" /></Field><label className="field"><span className="eyebrow">NOTAS</span><textarea name="notes" defaultValue={event?.notes ?? ''} /></label><Error text={error} /><button className="primary">Guardar</button></form></Modal>; }

function Attendance({ api, team, notify }) { const { data, refresh } = useLoad(() => api(`/teams/${team.id}/attendance`)); const [edit, setEdit] = useState(null); if (!data) return <Loading />; return <div className="stack"><Button onClick={() => setEdit({})}><Icon>add_task</Icon> Tomar asistencia</Button>{data.map(session => <button className="list-row selectable" key={session.id} onClick={() => setEdit(session)}><span><strong>{new Date(session.date).toLocaleDateString('es-AR')}</strong><small>{session.records.length} registros</small></span><Icon>chevron_right</Icon></button>)}{edit && <AttendanceEditor api={api} team={team} session={edit.id ? edit : null} close={() => setEdit(null)} done={() => { setEdit(null); refresh(); notify('Asistencia guardada'); }} />}</div>; }
function AttendanceEditor({ api, team, session, event: linkedEvent, close, done }) { const { data: players } = useLoad(() => api('/players')); const { data: savedSession } = useLoad(() => session?.id && !session.records ? api(`/attendance/${session.id}`) : Promise.resolve(session), [session?.id]); const [records, setRecords] = useState({}); const [error, setError] = useState(''); useEffect(() => setRecords(Object.fromEntries((savedSession?.records || []).map(x => [x.playerId, x.status]))), [savedSession?.id]); if (!players || (session && !savedSession)) return <Modal title="Asistencia" close={close}><Loading /></Modal>; const roster = players.filter(x => x.teams.some(t => t.teamId === team.id)); const setStatus = (id, status) => setRecords({ ...records, [id]: status }); return <Modal title="Asistencia" close={close}><form className="modal-form" onSubmit={async form => { form.preventDefault(); try { const body = { records: roster.map(p => ({ playerId: p.id, status: records[p.id] || 'PRESENT' })), ...(linkedEvent ? { eventId: linkedEvent.id } : {}) }; if (session) await api(`/attendance/${session.id}`, { method: 'PUT', body: JSON.stringify(body) }); else await api(`/teams/${team.id}/attendance`, { method: 'POST', body: JSON.stringify({ ...body, date: linkedEvent ? dateInput(linkedEvent.startsAt) : new FormData(form.currentTarget).get('date') }) }); done(); } catch (err) { setError(err.message); } }}><Field label="FECHA"><input name="date" type="date" defaultValue={dateInput(linkedEvent?.startsAt || savedSession?.date)} disabled={Boolean(session || linkedEvent)} required /></Field>{roster.map(player => <div className="attendance-row" key={player.id}><strong>{player.name}</strong><select value={records[player.id] || 'PRESENT'} onChange={e => setStatus(player.id, e.target.value)}><option value="PRESENT">Presente</option><option value="ABSENT">Ausente</option><option value="EXCUSED">Justificado</option></select></div>)}<Error text={error} /><button className="primary">Guardar asistencia</button></form></Modal>; }

function Statistics({ api, team }) { const { data, error } = useLoad(() => api(`/teams/${team.id}/statistics?months=6`)); if (!data) return <Loading />; const summary = data.summary || {}; return <div className="stack"><Error text={error} /><div className="stats-grid"><Stat label="Asistencia" value={`${Math.round(summary.attendanceRate || 0)}%`} /><Stat label="Presentes" value={summary.present || 0} /><Stat label="Ausentes" value={summary.absent || 0} /><Stat label="Justificados" value={summary.excused || 0} /></div>{(data.months || []).map(month => <div className="list-row" key={month.key}><span>{month.label || month.key}</span><strong>{Math.round(month.attendanceRate || 0)}%</strong></div>)}<span className="eyebrow">DETALLE POR JUGADOR</span>{(data.players || []).map(player => <div className="list-row" key={player.id}><span><strong>{player.name}</strong><small>{player.present || 0} presentes · {player.absent || 0} ausentes</small></span><strong>{Math.round(player.attendanceRate || 0)}%</strong></div>)}</div>; }
function Stat({ label, value }) { return <div className="card stat"><small>{label}</small><strong>{value}</strong></div>; }

function Plan({ api, team, notify }) { const { data, error, loading, refresh } = useLoad(() => api(`/teams/${team.id}/plan`), [team.id]); const [editing, setEditing] = useState(false); if (loading) return <Loading />; const labels = [['strengths', 'Fortalezas'], ['improvementAreas', 'Aspectos a mejorar'], ['weeklyFocus', 'Objetivo semanal'], ['monthlyFocus', 'Objetivo mensual'], ['seasonFocus', 'Objetivo de temporada']]; return <div className="stack"><Error text={error} /><div className="toolbar"><Button onClick={() => setEditing(true)}><Icon>edit_note</Icon> {data ? 'Editar plan' : 'Crear plan'}</Button>{data && <button className="text-action danger" onClick={async()=>{if(confirm('¿Eliminar plan de trabajo?')){await api(`/teams/${team.id}/plan`,{method:'DELETE'});refresh();notify('Plan eliminado');}}}>Eliminar</button>}</div>{data ? labels.map(([key, label]) => data[key] && <section className="plan-section" key={key}><span className="eyebrow">{label}</span><p>{data[key]}</p></section>) : <div className="empty">Todavía no hay plan de trabajo.</div>}{editing && <PlanEditor api={api} team={team} plan={data} close={() => setEditing(false)} done={() => { setEditing(false); refresh(); notify('Plan actualizado'); }} />}</div>; }
function PlanEditor({ api, team, plan, close, done }) { const [error, setError] = useState(''); const fields = [['strengths', 'FORTALEZAS'], ['improvementAreas', 'ASPECTOS A MEJORAR'], ['weeklyFocus', 'OBJETIVO SEMANAL'], ['monthlyFocus', 'OBJETIVO MENSUAL'], ['seasonFocus', 'OBJETIVO DE TEMPORADA']]; return <Modal title="Plan de trabajo" close={close}><form className="modal-form" onSubmit={async event => { event.preventDefault(); try { await api(`/teams/${team.id}/plan`, { method: 'PUT', body: JSON.stringify(Object.fromEntries(new FormData(event.currentTarget))) }); done(); } catch (err) { setError(err.message); } }}>{fields.map(([name, label]) => <label className="field" key={name}><span className="eyebrow">{label}</span><textarea name={name} defaultValue={plan?.[name] ?? ''} /></label>)}<Error text={error} /><button className="primary">Guardar plan</button></form></Modal>; }

function TeamStaff({ api, team, notify }) { const { data: assigned, refresh } = useLoad(() => api(`/teams/${team.id}/staff`)); const { data: users } = useLoad(() => api('/users')); if (!assigned || !users) return <Loading />; const ids = new Set(assigned.map(x => x.id)); return <div className="stack">{users.filter(user => !['DIRECTOR', 'SUBDIRECTOR'].includes(user.role)).map(user => <label className="list-row" key={user.id}><span><strong>{user.name}</strong><small>{roles[user.role]}</small></span><input type="checkbox" checked={ids.has(user.id)} onChange={async event => { await api(`/teams/${team.id}/staff/${user.id}`, { method: event.target.checked ? 'PUT' : 'DELETE' }); refresh(); notify('Personal actualizado'); }} /></label>)}</div>; }

function Stars({ value }) { return <span className="progress-stars" aria-label={value ? `${value} de 5` : 'Sin datos'}>{[1, 2, 3, 4, 5].map(item => <Icon key={item}>{(value || 0) >= item ? 'star' : 'star_outline'}</Icon>)}</span>; }
function ProgressNotes({ api, player, notify }) { const { data, refresh } = useLoad(() => api(`/players/${player.id}/progress-notes`)); const [editing, setEditing] = useState(null); if (!data) return <Loading />; const latest = data[0]; const scores = data.map(note => note.overallScore).filter(value => value !== null && value !== undefined); const values = scores.slice(0, 7).reverse(); const average = scores.length ? scores.reduce((total, value) => total + value, 0) / scores.length : null; return <div className="stack"><Button onClick={() => setEditing({})}><Icon>note_add</Icon> Nuevo seguimiento</Button><section className="progress-overview"><article className="card progress-summary"><div className="score-ring" style={{ '--score': `${(latest?.overallScore || 0) * 10}%` }}><strong>{latest?.overallScore?.toFixed(1) ?? '–'}</strong><small>/10</small></div><div><span className="eyebrow">ÚLTIMA EVALUACIÓN</span><strong>{latest ? new Date(latest.periodStart).toLocaleDateString('es-AR', { weekday: 'long', day: 'numeric', month: 'long' }) : 'Sin evaluaciones'}</strong><p>{latest?.comment || 'Registrá el primer seguimiento para comenzar a medir su evolución.'}</p></div></article><div className="progress-quick-stats"><div><small>Registros</small><strong>{data.length}</strong></div><div><small>Promedio</small><strong>{average?.toFixed(1) ?? '–'}<em>/10</em></strong></div></div></section><div className="progress-metrics"><ProgressMetric icon="local_fire_department" label="Intensidad media" value={{ LOW: 'Baja', MEDIUM: 'Media', HIGH: 'Alta' }[latest?.intensity] || 'Sin datos'} /><ProgressMetric icon="bolt" label="Esfuerzo" value={latest?.effort === null || latest?.effort === undefined ? 'Sin datos' : `${latest.effort}%`} /><ProgressMetric icon="favorite" label="Estado físico" value={latest?.physicalState === null || latest?.physicalState === undefined ? 'Sin datos' : `${latest.physicalState}%`} /><ProgressMetric icon="fitness_center" label="Carga de trabajo" value={{ LOW: 'Baja', OPTIMAL: 'Óptima', HIGH: 'Alta' }[latest?.workload] || 'Sin datos'} /></div><section className="card skills-card"><span className="eyebrow">CALIDAD DE EJERCICIOS</span><div><span>Tiro de 3 puntos</span><Stars value={latest?.shootingQuality} /></div><div><span>Defensa 1 vs 1</span><Stars value={latest?.defenseQuality} /></div><div><span>Sistemas ofensivos</span><Stars value={latest?.offenseQuality} /></div></section><section className="card evolution-card"><span className="eyebrow">EVOLUCIÓN RECIENTE</span>{values.length >= 2 ? <><div className="score-chart">{values.map((value, index) => <span key={index} style={{ height: `${value * 10}%` }} title={`${value}/10`} />)}</div><small>Puntaje general de los últimos {values.length} registros</small></> : <p className="muted">Se necesitan al menos dos registros con puntaje para mostrar la evolución.</p>}</section><span className="eyebrow">REGISTROS DE SEGUIMIENTO</span>{data.length ? data.map(note => <article className="card progress-record" key={note.id}><div><strong>{note.period === 'WEEKLY' ? 'Semanal' : 'Mensual'}</strong><small>{new Date(note.periodStart).toLocaleDateString('es-AR')}</small><p>{note.comment}</p><small>{note.author?.name}</small></div>{note.overallScore !== null && note.overallScore !== undefined && <b>{note.overallScore.toFixed(1)}</b>}<div><button className="text-action" onClick={() => setEditing(note)}>Editar</button><button className="text-action danger" onClick={async () => { if (confirm('¿Eliminar este seguimiento?')) { await api(`/progress-notes/${note.id}`, { method: 'DELETE' }); refresh(); notify('Seguimiento eliminado'); } }}>Eliminar</button></div></article>) : <div className="empty">Todavía no hay registros de seguimiento.</div>}{editing && <ProgressEditor api={api} player={player} note={editing.id ? editing : null} close={() => setEditing(null)} done={() => { setEditing(null); refresh(); notify('Seguimiento guardado'); }} />}</div>; }
function ProgressMetric({ icon, label, value }) { return <article className="card progress-metric"><span><Icon>{icon}</Icon>{label}</span><strong>{value}</strong></article>; }
function ProgressEditor({ api, player, note, close, done }) { const [error, setError] = useState(''); return <Modal title={note ? 'Editar seguimiento' : 'Seguimiento deportivo'} close={close}><form className="modal-form" onSubmit={async event => { event.preventDefault(); const data = Object.fromEntries(new FormData(event.currentTarget)); for (const key of ['overallScore', 'effort', 'shootingQuality', 'defenseQuality', 'offenseQuality', 'physicalState']) if (data[key] !== '') data[key] = Number(data[key]); else delete data[key]; try { await api(note ? `/progress-notes/${note.id}` : `/players/${player.id}/progress-notes`, { method: note ? 'PATCH' : 'POST', body: JSON.stringify(data) }); done(); } catch (err) { setError(err.message); } }}><Field label="PERÍODO"><select name="period" defaultValue={note?.period || 'WEEKLY'}><option value="WEEKLY">Semanal</option><option value="MONTHLY">Mensual</option></select></Field><Field label="INICIO DEL PERÍODO"><input name="periodStart" type="date" defaultValue={dateInput(note?.periodStart)} /></Field><label className="field"><span className="eyebrow">COMENTARIO DEPORTIVO</span><textarea name="comment" defaultValue={note?.comment} required /></label><Field label="PUNTAJE GENERAL (0–10)"><input name="overallScore" type="number" min="0" max="10" step="0.5" defaultValue={note?.overallScore ?? ''} /></Field><Field label="INTENSIDAD MEDIA"><select name="intensity" defaultValue={note?.intensity || ''}><option value="">Sin datos</option><option value="LOW">Baja</option><option value="MEDIUM">Media</option><option value="HIGH">Alta</option></select></Field><Field label="ESFUERZO (0–100)"><input name="effort" type="number" min="0" max="100" defaultValue={note?.effort ?? ''} /></Field><Field label="TIRO DE 3 PUNTOS (1–5)"><input name="shootingQuality" type="number" min="1" max="5" defaultValue={note?.shootingQuality ?? ''} /></Field><Field label="DEFENSA 1 VS 1 (1–5)"><input name="defenseQuality" type="number" min="1" max="5" defaultValue={note?.defenseQuality ?? ''} /></Field><Field label="SISTEMAS OFENSIVOS (1–5)"><input name="offenseQuality" type="number" min="1" max="5" defaultValue={note?.offenseQuality ?? ''} /></Field><Field label="ESTADO FÍSICO (0–100)"><input name="physicalState" type="number" min="0" max="100" defaultValue={note?.physicalState ?? ''} /></Field><Field label="CARGA DE TRABAJO"><select name="workload" defaultValue={note?.workload || ''}><option value="">Sin datos</option><option value="LOW">Baja</option><option value="OPTIMAL">Óptima</option><option value="HIGH">Alta</option></select></Field><Error text={error} /><button className="primary">Guardar</button></form></Modal>; }

export function StaffWorkspace({ api, notify, canInvite }) { const { data: users, refresh } = useLoad(() => api('/users')); const { data: invitations, refresh: refreshInvitations } = useLoad(() => api('/users/invitations')); const [invite, setInvite] = useState(false); if (!users || !invitations) return <Loading />; return <><header className="page-head"><div><span className="eyebrow">ORGANIZACIÓN</span><h1>Personal</h1><p className="subtitle">Miembros, roles e invitaciones de la organización.</p></div>{canInvite && <Button onClick={() => setInvite(true)}><Icon>person_add</Icon> Invitar</Button>}</header><div className="list staff-list">{users.map(user => <div className="card list-row" key={user.id}><span><strong>{user.name}</strong><small>{user.email}</small></span>{user.role === 'DIRECTOR' ? <span className="role-label">Director</span> : <select value={user.role} onChange={async event => { await api(`/users/${user.id}/role`, { method: 'PATCH', body: JSON.stringify({ role: event.target.value }) }); refresh(); notify('Rol actualizado'); }}><option value="SUBDIRECTOR">Subdirector</option><option value="COACH">Entrenador</option><option value="MONITOR">Monitor</option></select>}</div>)}</div><p className="section eyebrow">INVITACIONES PENDIENTES</p><div className="list staff-list">{invitations.map(item => <div className="card list-row" key={item.id}><span><strong>{item.email}</strong><small>{roles[item.role]}</small></span><button className="text-action danger" onClick={async () => { await api(`/users/invitations/${item.id}`, { method: 'DELETE' }); refreshInvitations(); }}>Revocar</button></div>)}</div>{invite && <InviteStaff api={api} close={() => setInvite(false)} done={() => { setInvite(false); refreshInvitations(); notify('Invitación creada'); }} />}</>; }
function InviteStaff({ api, close, done }) { const [result, setResult] = useState(null); const [error, setError] = useState(''); return <Modal title="Invitar personal" close={close}>{result ? <div className="stack"><p>Invitación creada para <strong>{result.email}</strong>.</p>{result.invitationToken && <><p className="notice">Copiá este código para desarrollo:</p><code className="token">{result.invitationToken}</code></>}<Button onClick={done}>Cerrar</Button></div> : <form className="modal-form" onSubmit={async event => { event.preventDefault(); try { setResult(await api('/users/invitations', { method: 'POST', body: JSON.stringify(Object.fromEntries(new FormData(event.currentTarget))) })); } catch (err) { setError(err.message); } }}><Field label="EMAIL"><input name="email" type="email" required /></Field><Field label="ROL"><select name="role"><option value="SUBDIRECTOR">Subdirector</option><option value="COACH">Entrenador</option><option value="MONITOR">Monitor</option></select></Field><Error text={error} /><button className="primary">Enviar invitación</button></form>}</Modal>; }

export function AccountWorkspace({ api, user, signOut }) { const [deleteOpen, setDeleteOpen] = useState(false); return <><header className="page-head"><div><span className="eyebrow">CUENTA</span><h1>Perfil</h1><p className="subtitle">{user.email} · {roles[user.role]}</p></div></header><section className="card profile-card"><div className="list-row"><span className="avatar avatar-large">{initials(user.name)}</span><span><strong>{user.name}</strong><small>{roles[user.role]}</small></span></div><button className="text-action danger" onClick={() => setDeleteOpen(true)}>Eliminar cuenta</button></section>{deleteOpen && <DeleteAccount api={api} user={user} close={() => setDeleteOpen(false)} signOut={signOut} />}</>; }
function DeleteAccount({ api, user, close, signOut }) { const confirmation = user.role === 'DIRECTOR' ? 'ELIMINAR ORGANIZACION' : 'ELIMINAR CUENTA'; const [error, setError] = useState(''); return <Modal title="Eliminar cuenta" close={close}><form className="modal-form" onSubmit={async event => { event.preventDefault(); try { await api('/auth/account', { method: 'DELETE', body: JSON.stringify(Object.fromEntries(new FormData(event.currentTarget))) }); signOut(); } catch (err) { setError(err.message); } }}><p className="error">Esta acción no se puede deshacer.</p><Field label="CONTRASEÑA"><input name="password" type="password" minLength="10" required /></Field><Field label={`ESCRIBÍ ${confirmation}`}><input name="confirmation" required /></Field><Error text={error} /><button className="primary">Confirmar eliminación</button></form></Modal>; }
